import{_ as n,o as s,c as a,f as t,a as e}from"./app-v4ODCOL5.js";const o={},p=e(`<h2 id="第-15-章-typescript" tabindex="-1"><a class="header-anchor" href="#第-15-章-typescript" aria-hidden="true">#</a> 第 15 章 TypeScript</h2><h3 id="q1-typescript-比-javascript-好在哪-用它有什么代价" tabindex="-1"><a class="header-anchor" href="#q1-typescript-比-javascript-好在哪-用它有什么代价" aria-hidden="true">#</a> Q1 TypeScript 比 JavaScript 好在哪？用它有什么代价？</h3><p><strong>考察点</strong>：考的是价值与成本的取舍判断，不是背&quot;TS 是 JS 的超集&quot;。答出&quot;编译期检查 + 类型擦除 + 什么项目值得上&quot;才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：TypeScript 的价值是把类型错误从运行时前移到编译期，并用类型充当可被工具消费的文档；代价是编写与检查成本、类型体操的可读性损耗，以及与无类型生态的摩擦。</p></blockquote><ol><li>收益一：静态检查。拼错属性名、少传参数、把 string 当 number 用，编译期就报错，不用等线上白屏。</li><li>收益二：工具能力。IDE 补全、跳转、重命名重构都依赖类型信息，这是大项目维护效率的主要来源。</li><li>收益三：协作契约。接口形状写进类型后，前后端、多人协作时不用靠口头约定。</li><li>成本一：要写类型、要维护 tsconfig、CI 要多跑一遍类型检查；第三方库缺类型时还要自己补 <code>.d.ts</code>。</li><li>成本二：类型写得过深（类型体操）会牺牲可读性和编译速度，<code>any</code> 泛滥则让收益直接归零。</li><li>判断：中大型、多人、生命周期长的项目收益最大；一次性脚本、原型验证收益有限。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：TS 能保证运行时不报错吗？答：不能，类型只在编译期存在，编译后会被擦除（Type Erasure），接口返回的数据形状它管不到。</li><li>陷阱：只说&quot;TS 是 JS 的超集所以更安全&quot;太浅，必须补上&quot;类型擦除&quot;和&quot;只在编译期生效&quot;这两点。</li></ul><h3 id="q2-听说-typescript-的类型系统是结构化的-和-java-那种有什么区别" tabindex="-1"><a class="header-anchor" href="#q2-听说-typescript-的类型系统是结构化的-和-java-那种有什么区别" aria-hidden="true">#</a> Q2 听说 TypeScript 的类型系统是结构化的，和 Java 那种有什么区别？</h3><p><strong>考察点</strong>：考结构化类型（Structural Typing，俗称鸭子类型）与名义类型（Nominal Typing）的本质差异，以及 TS 里少数名义性来源。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：TS 只看类型的&quot;形状&quot;是否兼容，不看你有没有显式声明继承或实现；Java/C# 看声明关系，名字对不上就不兼容。</p></blockquote><ol><li>结构化的含义：只要成员的名称与类型匹配，两个类型就互相兼容，不需要 <code>implements</code>，也不需要继承同一父类。</li><li>名义类型的含义：必须显式声明 <code>implements IUser</code> 才算实现，形状相同也没用，好处是能防止语义不同的类型互相赋值。</li><li>TS 里残留的名义性：类的 <code>private</code>/<code>protected</code> 成员只有在同一处声明时才兼容，这让带私有成员的类之间变成名义比较；<code>enum</code> 成员也近似名义。</li><li>结构化的坑：偶然兼容（Accidental Compatibility）。<code>UserId</code> 和 <code>OrderId</code> 都是 string，互相赋值不报错。</li><li>补救办法：品牌类型（Branded Type），用交叉类型伪造一个不存在的成员，模拟名义类型。</li><li>结构化的好处：天然适配 JS 生态，不用改运行时就能给第三方库补类型。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">interface</span> <span class="token class-name">Point</span> <span class="token punctuation">{</span> x<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> y<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span>
<span class="token keyword">class</span> <span class="token class-name">Vec</span> <span class="token punctuation">{</span> <span class="token function">constructor</span><span class="token punctuation">(</span><span class="token keyword">public</span> x<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">,</span> <span class="token keyword">public</span> y<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">}</span>
<span class="token keyword">const</span> p<span class="token operator">:</span> Point <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Vec</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 结构兼容，无需 implements</span>

<span class="token comment">// 品牌类型：模拟名义类型，防止两个 string 语义互串</span>
<span class="token keyword">type</span> <span class="token class-name">UserId</span> <span class="token operator">=</span> <span class="token builtin">string</span> <span class="token operator">&amp;</span> <span class="token punctuation">{</span> <span class="token keyword">readonly</span> __brand<span class="token operator">:</span> <span class="token string">&#39;UserId&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> id <span class="token operator">=</span> <span class="token string">&#39;u_1&#39;</span> <span class="token keyword">as</span> UserId<span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：结构化类型最常见的线上事故是什么？答：把两个形状相同但业务含义不同的对象互相传递，比如把后端返回的分页对象当成用户对象，用 Brand 或独立字段区分。</li><li>陷阱：说&quot;TS 完全是结构化类型&quot;不严谨，<code>private</code> 成员和 <code>enum</code> 是例外。</li></ul><h3 id="q3-ts-有哪些基础类型-类型推断是怎么工作的" tabindex="-1"><a class="header-anchor" href="#q3-ts-有哪些基础类型-类型推断是怎么工作的" aria-hidden="true">#</a> Q3 TS 有哪些基础类型？类型推断是怎么工作的？</h3><p><strong>考察点</strong>：考基础类型清单是否完整，以及字面量扩宽（Literal Widening）、上下文类型（Contextual Typing）这两个推断规则。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：基础类型是 boolean、number、string、bigint、symbol、null、undefined、object，加上 TS 特有的 any、unknown、never、void、字面量类型、元组和 enum；推断分&quot;从值推断&quot;与&quot;从上下文推断&quot;两条路。</p></blockquote><ol><li>从值推断：<code>let a = &#39;x&#39;</code> 推断为 <code>string</code>（扩展为宽类型），<code>const b = &#39;x&#39;</code> 推断为字面量类型 <code>&#39;x&#39;</code>；对象属性遵循 <code>let</code> 语义，所以 <code>{ n: 1 }</code> 的属性是 <code>number</code>。</li><li>数组与元组：<code>[1, 2]</code> 推断为 <code>number[]</code>，要固定长度和逐位类型必须显式写 <code>[number, number]</code> 或用 <code>as const</code>。</li><li>函数推断：返回值类型由 return 语句推断；参数没有默认值又没标注时是隐式 any（<code>noImplicitAny</code> 会报错）。</li><li>上下文类型：回调参数由调用处的期望类型推断出来，例如 <code>[1].map(n =&gt; n.toFixed())</code> 里的 <code>n</code> 是 number，不需要手写。</li><li>object 与 Object 与 <code>{}</code> 三者不同：<code>object</code> 指非原始值，<code>Object</code> 指有 toString 的任意值，<code>{}</code> 几乎是&quot;除 null/undefined 外的一切&quot;。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">let</span> a <span class="token operator">=</span> <span class="token string">&#39;x&#39;</span><span class="token punctuation">;</span>           <span class="token comment">// string</span>
<span class="token keyword">const</span> b <span class="token operator">=</span> <span class="token string">&#39;x&#39;</span><span class="token punctuation">;</span>         <span class="token comment">// &#39;x&#39;</span>
<span class="token keyword">const</span> cfg <span class="token operator">=</span> <span class="token punctuation">{</span> mode<span class="token operator">:</span> <span class="token string">&#39;dark&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token comment">// { mode: string }</span>
<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span>n<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> n<span class="token punctuation">.</span><span class="token function">toFixed</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// n 由上下文推断为 number</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>const obj = { n: 1 }</code> 的 n 不是字面量 1？答：const 只固定绑定，属性仍可改，所以属性会被扩宽；要保留字面量用 <code>as const</code>。</li><li>陷阱：把 <code>{}</code> 当成&quot;空对象类型&quot;，实际上非空对象也能赋给它，它只排除 null 和 undefined。</li></ul><h3 id="q4-any、unknown、never、void、object-这几个类型到底怎么选" tabindex="-1"><a class="header-anchor" href="#q4-any、unknown、never、void、object-这几个类型到底怎么选" aria-hidden="true">#</a> Q4 any、unknown、never、void、object 这几个类型到底怎么选？</h3><p><strong>考察点</strong>：考查对类型论里顶类型与底类型的理解，以及实际选型纪律。这是高频送分题，答错会被判定基础不牢。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：any 是关掉检查的逃生舱，unknown 是安全的 any（用之前必须收窄），never 是没有任何值的底类型，void 只表示&quot;返回值无意义&quot;，object 表示非原始类型。</p></blockquote><table><thead><tr><th>类型</th><th>语义</th><th>使用建议</th></tr></thead><tbody><tr><td>any</td><td>双向兼容，放弃检查</td><td>只在迁移旧代码时临时用，禁止扩散</td></tr><tr><td>unknown</td><td>顶类型，只能赋给 any/unknown</td><td>外部输入（接口、JSON、catch）首选</td></tr><tr><td>never</td><td>底类型，没有任何值</td><td>穷尽检查兜底、Exclude 过滤</td></tr><tr><td>void</td><td>函数返回值可忽略</td><td>回调、事件处理器的返回类型</td></tr><tr><td>object</td><td>非原始值（不含 null）</td><td>泛型约束 <code>&lt;T extends object&gt;</code></td></tr></tbody></table><ol><li>any 的传染性：一个 any 参与运算后结果还是 any，等于在类型网里开了洞。</li><li>unknown 的正确姿势：先收窄再使用，<code>typeof</code>、<code>in</code>、<code>instanceof</code>、类型谓词都可以。</li><li>never 的三个用途：函数永不正常返回（抛异常或死循环）、穷尽检查兜底、条件类型里表示&quot;剔除&quot;。</li><li>void 的特例：返回值类型为 void 的回调，允许传入返回任意值的函数，这是 TS 有意放宽的规则。</li><li><code>object</code> 与 <code>Object</code> 不要混用：<code>{}</code> 也不是&quot;空对象&quot;。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：never 和 void 有什么区别？答：void 的函数能正常返回 undefined；never 的函数永远不会正常返回，<code>const x: never</code> 无法被赋值。</li><li>追问：什么时候用 unknown 而不是 any？答：凡是数据来自外部（fetch 结果、<code>JSON.parse</code>、<code>catch</code> 的 error、第三方回调参数）都用 unknown。</li><li>陷阱：说&quot;never 就是永远不执行&quot;不准确，它是&quot;没有值可返回&quot;这个类型层面的描述。</li></ul><h3 id="q5-null-和-undefined-有什么区别-strictnullchecks-打开后有什么变化" tabindex="-1"><a class="header-anchor" href="#q5-null-和-undefined-有什么区别-strictnullchecks-打开后有什么变化" aria-hidden="true">#</a> Q5 null 和 undefined 有什么区别？strictNullChecks 打开后有什么变化？</h3><p><strong>考察点</strong>：考空值语义与严格模式开关的实际影响，能不能说清&quot;打开前可以乱赋、打开后必须显式处理&quot;。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：undefined 表示&quot;未赋值/不存在&quot;，null 表示&quot;有意置空&quot;；打开 strictNullChecks 后 null 与 undefined 变成独立类型，不再能赋给其他类型，必须显式联合声明并处理。</p></blockquote><ol><li>语义差异：<code>let a;</code> 是 undefined；<code>JSON.stringify({ a: null })</code> 保留 null 而丢掉 undefined；对象属性缺失是 undefined，后端&quot;清空&quot;字段通常给 null。</li><li>开关前（关闭 strictNullChecks）：null 和 undefined 可赋给任何类型，<code>undefined.foo</code> 这类错误检查不出来。</li><li>开关后：必须写成 <code>string | undefined</code>，<code>arr.find()</code> 返回 <code>T | undefined</code>，取值前必须判空或用可选链。</li><li><code>strict: true</code> 是一个家族：它等于打开 strictNullChecks、noImplicitAny、strictFunctionTypes、strictBindCallApply、strictPropertyInitialization、noImplicitThis、alwaysStrict、useUnknownInCatchVariables。</li><li>可选属性的细节：<code>foo?: string</code> 等价于 <code>string | undefined</code>，除非开启 <code>exactOptionalPropertyTypes</code> 才区分&quot;不存在&quot;和&quot;存在但为 undefined&quot;。</li><li>非空断言 <code>!</code> 只是删掉 null/undefined，不做任何运行时检查，滥用等于关掉这个开关。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>catch (e)</code> 里 e 是 unknown？答：tsconfig 的 useUnknownInCatchVariables 随 strict 打开，因为抛出的可能是任何值，必须先收窄。</li><li>陷阱：<code>?.</code> 和 <code>??</code> 是 ES2020 的运行时语法，跟 strictNullChecks 无关，别把两者说成一回事。</li></ul><h3 id="q6-类型断言-as-什么时候能用-双重断言有什么风险" tabindex="-1"><a class="header-anchor" href="#q6-类型断言-as-什么时候能用-双重断言有什么风险" aria-hidden="true">#</a> Q6 类型断言 as 什么时候能用？双重断言有什么风险？</h3><p><strong>考察点</strong>：考断言是编译期承诺而非转换，以及&quot;可比较类型&quot;的规则与替代方案。这是最容易被追问穿的一题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>as</code> 只是告诉编译器&quot;信我&quot;，运行时不做任何转换和校验；当两个类型不可比较时必须写成 <code>x as unknown as T</code>，那等于彻底放弃检查，是最该被 Code Review 拦下的写法。</p></blockquote><ol><li>合法断言条件：目标类型是源类型的父类型或子类型（可比较）；否则报错 <code>Conversion of type &#39;X&#39; to type &#39;Y&#39; may be a mistake</code>。</li><li>双重断言的原理：先用 <code>as unknown</code> 把值变成顶类型，再断言成任意目标类型，于是编译器失去了所有判断依据。</li><li>风险：类型与实际运行时值不符时，编译期一片安静，报错发生在使用时，比如 <code>Cannot read properties of undefined</code>。</li><li>必须用 as 的场景：DOM API 返回基类（<code>getElementById</code> 返回 <code>HTMLElement | null</code>）、第三方库类型有误、测试里构造 mock 数据。</li><li>更规范的替代：优先用类型守卫（<code>instanceof HTMLInputElement</code>）和泛型约束，让编译器自己收窄；数据边界用运行时校验。</li><li>同理，<code>!</code> 非空断言只删 null/undefined，<code>@ts-ignore</code> 会吞掉整行错误，优先 <code>@ts-expect-error</code>（没错时反而报错）。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">const</span> el <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// HTMLElement | null</span>
<span class="token comment">// @ts-expect-error HTMLElement 上没有 value，而且它还可能是 null</span>
el<span class="token punctuation">.</span>value<span class="token punctuation">;</span>
<span class="token punctuation">(</span>el <span class="token keyword">as</span> HTMLInputElement<span class="token punctuation">)</span><span class="token punctuation">.</span>value<span class="token punctuation">;</span>               <span class="token comment">// 断言能过编译，但不安全</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>el <span class="token keyword">instanceof</span> <span class="token class-name">HTMLInputElement</span><span class="token punctuation">)</span> el<span class="token punctuation">.</span>value<span class="token punctuation">;</span> <span class="token comment">// 推荐：编译器自动收窄</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>as</code> 和 <code>as const</code> 是一回事吗？答：不是，<code>as const</code> 是字面量推断修饰，不是类型断言，不涉及&quot;欺骗编译器&quot;。</li><li>追问：双重断言在什么情况下其实是合理的？答：明确的类型收窄且无法用守卫表达时（如事件对象到自定义事件），必须写注释说明理由。</li><li>陷阱：把 <code>as</code> 理解成类型转换函数（类似 <code>Number(x)</code>），实际上它编译后完全消失。</li></ul><h3 id="q7-拿到一个-unknown-该怎么安全取值-四种类型守卫怎么选" tabindex="-1"><a class="header-anchor" href="#q7-拿到一个-unknown-该怎么安全取值-四种类型守卫怎么选" aria-hidden="true">#</a> Q7 拿到一个 unknown 该怎么安全取值？四种类型守卫怎么选？</h3><p><strong>考察点</strong>：考窄化（Narrowing）的实际写法，尤其是自定义谓词 <code>is</code> 需要自己承担正确性责任这一点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：用 typeof、instanceof、in、自定义类型谓词把 unknown 逐层窄化成可信类型；前三种由编译器验证，<code>is</code> 谓词是&quot;你对编译器的承诺&quot;，写错编译器不会拦。</p></blockquote><ol><li><code>typeof</code>：适合原始类型，注意 <code>typeof null === &#39;object&#39;</code>，所以判对象前要先排除 null；<code>typeof fn === &#39;function&#39;</code> 可用。</li><li><code>instanceof</code>：适合类实例（Date、Error、自定义类），跨 iframe 或跨 realm 时原型链不同会失效。</li><li><code>in</code>：判断属性是否存在，适合按字段区分对象形状，天然衔接可辨识联合。</li><li>自定义谓词：返回类型写成 <code>v is User</code>，函数体里做完整校验；断言函数写成 <code>asserts v is User</code>，适用于&quot;不满足就抛错&quot;的场景。</li><li>收窄是控制流分析的产物：<code>if</code>、<code>switch</code>、<code>??</code>、<code>Array.isArray</code>、真值判断都会让编译器更新类型。</li><li>纪律：谓词函数必须真的校验所有关键字段，否则等于把 any 换了个名字。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">User</span> <span class="token operator">=</span> <span class="token punctuation">{</span> name<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> age<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">function</span> <span class="token function">isUser</span><span class="token punctuation">(</span>v<span class="token operator">:</span> <span class="token builtin">unknown</span><span class="token punctuation">)</span><span class="token operator">:</span> v <span class="token keyword">is</span> User <span class="token punctuation">{</span>
  <span class="token keyword">return</span> <span class="token keyword">typeof</span> v <span class="token operator">===</span> <span class="token string">&#39;object&#39;</span> <span class="token operator">&amp;&amp;</span> v <span class="token operator">!==</span> <span class="token keyword">null</span>
    <span class="token operator">&amp;&amp;</span> <span class="token keyword">typeof</span> <span class="token punctuation">(</span>v <span class="token keyword">as</span> <span class="token punctuation">{</span> name<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">unknown</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span>name <span class="token operator">===</span> <span class="token string">&#39;string&#39;</span>
    <span class="token operator">&amp;&amp;</span> <span class="token keyword">typeof</span> <span class="token punctuation">(</span>v <span class="token keyword">as</span> <span class="token punctuation">{</span> age<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">unknown</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span>age <span class="token operator">===</span> <span class="token string">&#39;number&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function">assertIsUser</span><span class="token punctuation">(</span>v<span class="token operator">:</span> <span class="token builtin">unknown</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">asserts</span> v <span class="token keyword">is</span> User <span class="token punctuation">{</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">isUser</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">TypeError</span><span class="token punctuation">(</span><span class="token string">&#39;not a User&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>in</code> 判断有什么坑？答：只能证明属性存在，不能证明类型正确，而且对数组、原型链上的属性也会为真。</li><li>追问：为什么不直接 <code>as User</code> 省事？答：断言不产生运行时校验，接口字段缺失时崩在业务代码深处，守卫会把问题挡在边界处。</li><li>陷阱：谓词里漏判某个字段，编译器完全不会提醒你，这是最隐蔽的类型漏洞。</li></ul><h3 id="q8-字面量类型和-as-const-怎么用-satisfies-又解决什么问题" tabindex="-1"><a class="header-anchor" href="#q8-字面量类型和-as-const-怎么用-satisfies-又解决什么问题" aria-hidden="true">#</a> Q8 字面量类型和 as const 怎么用？satisfies 又解决什么问题？</h3><p><strong>考察点</strong>：考字面量类型与只读推断，以及 TS 4.9 的 satisfies 与类型注解的本质差异。现代项目高频。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>as const</code> 让推断结果保持字面量并加上 readonly；<code>satisfies</code>（TS 4.9 起）在&quot;校验是否符合某类型&quot;的同时保留更精确的推断，而 <code>: T</code> 注解会把类型放大成 T。</p></blockquote><ol><li>字面量类型：<code>&#39;dark&#39; | &#39;light&#39;</code>、<code>42</code>、<code>true</code> 都是类型，是联合类型收窄与穷尽检查的基础。</li><li><code>as const</code> 的三个效果：字符串/数字保留字面量、对象所有属性变 readonly、数组变只读元组 <code>readonly [1, 2]</code>。</li><li>典型用途：路由表、常量枚举替代品、<code>(typeof TABLE)[keyof typeof TABLE]</code> 生成联合类型。</li><li>satisfies 的核心价值：既能检查属性拼写和类型，又不会把字面量扩宽；用 <code>: T</code> 注解则会丢失字面量信息。</li><li>satisfies 还会做多余属性检查，能提前发现写错键名；它不改变运行时，也不做窄化。</li><li>常见组合：对象用 satisfies 校验结构，同时用 <code>as const</code> 或字面量推断导出联合类型。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">const</span> routes <span class="token operator">=</span> <span class="token punctuation">{</span> home<span class="token operator">:</span> <span class="token string">&#39;/&#39;</span><span class="token punctuation">,</span> user<span class="token operator">:</span> <span class="token string">&#39;/user/:id&#39;</span> <span class="token punctuation">}</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">Path</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> routes<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token keyword">keyof</span> <span class="token keyword">typeof</span> routes<span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token comment">// &#39;/&#39; | &#39;/user/:id&#39;</span>

<span class="token keyword">const</span> cfg <span class="token operator">=</span> <span class="token punctuation">{</span> mode<span class="token operator">:</span> <span class="token string">&#39;dark&#39;</span><span class="token punctuation">,</span> retry<span class="token operator">:</span> <span class="token number">3</span> <span class="token punctuation">}</span> satisfies <span class="token punctuation">{</span> mode<span class="token operator">:</span> <span class="token string">&#39;dark&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;light&#39;</span><span class="token punctuation">;</span> retry<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
cfg<span class="token punctuation">.</span>mode<span class="token punctuation">;</span> <span class="token comment">// &#39;dark&#39;，而 const c: { mode: &#39;dark&#39; | &#39;light&#39; } = ... 会丢成 &#39;dark&#39; | &#39;light&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：satisfies 能替代 as 吗？答：不能，satisfies 只做校验不做断言，类型不匹配时直接报错，这正是它比 as 安全的地方。</li><li>陷阱：<code>as const</code> 只能用于字面量表达式，<code>as const</code> 加在变量上再改动会直接报错（readonly）。</li></ul><h3 id="q9-联合类型和交叉类型分别是什么-用起来有什么区别" tabindex="-1"><a class="header-anchor" href="#q9-联合类型和交叉类型分别是什么-用起来有什么区别" aria-hidden="true">#</a> Q9 联合类型和交叉类型分别是什么？用起来有什么区别？</h3><p><strong>考察点</strong>：考 <code>|</code> 与 <code>&amp;</code> 的语义差异、never/unknown 在其中的吸收规律，以及&quot;联合访问属性要先收窄&quot;。</p><table><thead><tr><th>运算</th><th>语义</th><th>常见用途</th></tr></thead><tbody><tr><td><code>A | B</code></td><td>值属于其中至少一种</td><td>状态机、可辨识联合、可选输入</td></tr><tr><td><code>A &amp; B</code></td><td>同时满足两种形状</td><td>混入扩展、合并多个 props 类型</td></tr></tbody></table><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：联合是&quot;或&quot;，只能安全访问公共成员；交叉是&quot;且&quot;，成员全部可见；never 是联合的单位元、交叉的零元，unknown 在联合中吸收一切。</p></blockquote><ol><li>联合访问限制：<code>string | number</code> 上只能调用两者共有的方法，想用各自特有成员必须先收窄。</li><li>交叉是类型层面的合并：<code>A &amp; B</code> 同时具备两者成员，常用于把多个来源的类型拼起来，运行时不存在这个&quot;新类型&quot;。</li><li>恒等式：<code>T | never = T</code>，<code>T &amp; never = never</code>，<code>T | unknown = unknown</code>，这是 Exclude 与 UnionToIntersection 的原理基础。</li><li>冲突字段：<code>{ a: string } &amp; { a: number }</code> 不会报错，但 <code>a</code> 的类型变成 never，实际无法赋任何值。</li><li>交叉与继承的差别：<code>interface A extends B</code> 遇到冲突属性会直接报错，交叉类型会静默产生 never，后者更难排查。</li><li>数组上的区别：<code>(A | B)[]</code> 表示元素可能是 A 或 B，<code>A[] | B[]</code> 表示整个数组只能是 A 数组或 B 数组，两者完全不同。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么交叉类型可能让类型检查变慢？答：交叉类型没有缓存，深层交叉要反复计算成员，项目里大范围滥用会拖慢 tsserver。</li><li>陷阱：以为 <code>A &amp; B</code> 会在运行时把对象合并，实际要合并对象得用展开运算符或 Object.assign。</li></ul><h3 id="q10-可辨识联合怎么写-为什么-default-分支里赋值给-never-能做穷尽检查-never-在-exclude-里又起什么作用" tabindex="-1"><a class="header-anchor" href="#q10-可辨识联合怎么写-为什么-default-分支里赋值给-never-能做穷尽检查-never-在-exclude-里又起什么作用" aria-hidden="true">#</a> Q10 可辨识联合怎么写？为什么 default 分支里赋值给 never 能做穷尽检查？never 在 Exclude 里又起什么作用？</h3><p><strong>考察点</strong>：考可辨识联合（Discriminated Union）建模 + 穷尽检查（Exhaustive Check）原理 + never 作为底类型的两个用途，是本篇最核心的进阶题。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：给每个成员加一个字面量判别字段，switch 收窄后所有分支都覆盖时变量类型变成 never；never 可赋给任何类型，所以赋值不报错，漏掉分支就会立刻报错。同样的机制让 Exclude 能用 never 表示&quot;删除&quot;。</p></blockquote><ol><li>建模：每个联合成员都有同一个字面量字段（如 <code>kind</code>），这是可辨识性的来源。</li><li>收窄：<code>switch (s.kind)</code> 的每个 case 都能把 s 精确收窄到对应成员，不用 as。</li><li>穷尽检查：default 分支里把 s 赋给 <code>never</code> 变量，新增成员时这里报错，等于让编译器替你做回归测试。</li><li>为什么成立：分支全覆盖后 s 的类型是 never，而 never 是所有类型的子类型，可以赋给任何变量；漏掉分支时 s 还有剩余类型，赋值失败。</li><li>Exclude 里的 never：<code>type Exclude&lt;T, U&gt; = T extends U ? never : T</code> 用 never 表示&quot;这个成员被剔除&quot;，而联合吸收 never，所以结果就是删掉后的联合。</li><li>实践建议：把兜底写成 <code>assertNever</code> 函数，报错信息更有指向性，也能跨模块复用。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">Shape</span> <span class="token operator">=</span>
  <span class="token operator">|</span> <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&#39;circle&#39;</span><span class="token punctuation">;</span> r<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span>
  <span class="token operator">|</span> <span class="token punctuation">{</span> kind<span class="token operator">:</span> <span class="token string">&#39;rect&#39;</span><span class="token punctuation">;</span> w<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> h<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">function</span> <span class="token function">assertNever</span><span class="token punctuation">(</span>x<span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">never</span> <span class="token punctuation">{</span>
  <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">unexpected value: </span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">JSON</span><span class="token punctuation">.</span><span class="token function">stringify</span><span class="token punctuation">(</span>x<span class="token punctuation">)</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">function</span> <span class="token function">area</span><span class="token punctuation">(</span>s<span class="token operator">:</span> Shape<span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">{</span>
  <span class="token keyword">switch</span> <span class="token punctuation">(</span>s<span class="token punctuation">.</span>kind<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">case</span> <span class="token string">&#39;circle&#39;</span><span class="token operator">:</span> <span class="token keyword">return</span> Math<span class="token punctuation">.</span><span class="token constant">PI</span> <span class="token operator">*</span> s<span class="token punctuation">.</span>r <span class="token operator">**</span> <span class="token number">2</span><span class="token punctuation">;</span>
    <span class="token keyword">case</span> <span class="token string">&#39;rect&#39;</span><span class="token operator">:</span> <span class="token keyword">return</span> s<span class="token punctuation">.</span>w <span class="token operator">*</span> s<span class="token punctuation">.</span>h<span class="token punctuation">;</span>
    <span class="token keyword">default</span><span class="token operator">:</span> <span class="token keyword">return</span> <span class="token function">assertNever</span><span class="token punctuation">(</span>s<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 新增成员时这一行报错</span>
  <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不用 <code>default: throw new Error()</code> 直接兜底？答：那样新增成员时不会报错，穷尽检查的价值就没了，必须显式赋给 never 或调用 assertNever。</li><li>追问：判别字段只能是字符串吗？答：数字字面量、布尔也可以，只要是每个成员唯一的字面量类型。</li><li>陷阱：判别字段写成 <code>string</code> 而不是字面量（如 <code>kind: string</code>），整个联合就退化，收窄和穷尽检查全部失效。</li></ul><h3 id="q11-interface-和-type-有什么区别-实际项目怎么选" tabindex="-1"><a class="header-anchor" href="#q11-interface-和-type-有什么区别-实际项目怎么选" aria-hidden="true">#</a> Q11 interface 和 type 有什么区别？实际项目怎么选？</h3><p><strong>考察点</strong>：考两者的能力边界与生态差异，不是背&quot;基本一样&quot;。要能说出合并、扩展、能力范围、错误信息四个维度。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：两者描述对象时高度重叠，但 interface 支持声明合并、错误信息更可读、扩展用 extends；type 能表达联合、元组、条件类型等一切类型运算。项目里对象形状用 interface，其他类型运算用 type。</p></blockquote><table><thead><tr><th>维度</th><th>interface</th><th>type</th></tr></thead><tbody><tr><td>扩展方式</td><td><code>extends</code>（可多继承）</td><td><code>&amp;</code> 交叉</td></tr><tr><td>声明合并</td><td>支持（同名自动合并）</td><td>不支持，重名报错</td></tr><tr><td>表达能力</td><td>只能描述对象/函数/类形状</td><td>联合、元组、条件类型、映射类型</td></tr><tr><td>错误信息</td><td>通常更简短可读</td><td>展开后可能很长</td></tr><tr><td>性能</td><td>有缓存，扩展更快</td><td>交叉类型需重新计算</td></tr></tbody></table><ol><li>扩展差异：<code>interface A extends B</code> 遇到同名属性类型冲突会直接报错；<code>type A = B &amp; C</code> 会静默产生 never，更隐蔽。</li><li>声明合并：interface 同名会合并成员，这是给第三方库做类型增强的基础；type 无法合并。</li><li>能力边界：type 可以写 <code>type ID = string | number</code>、<code>type T = [string, number]</code>，interface 做不到。</li><li>选型建议：组件 props、接口响应对象、公共 API 用 interface；工具类型、联合、元组、函数重载签名集合用 type。</li><li>团队一致性优先：项目内统一风格比&quot;哪个更好&quot;更重要，混用会让人反复判断。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么不少框架源码偏爱 interface？答：可扩展（用户能做模块增强）、有缓存、生成 .d.ts 时错误信息更友好。</li><li>陷阱：说&quot;type 不能被 extends&quot;是错的，type 定义的对象一样能被 interface extends（只要它是静态已知的对象类型）。</li></ul><h3 id="q12-声明合并和模块增强是怎么回事-namespace-还能用吗" tabindex="-1"><a class="header-anchor" href="#q12-声明合并和模块增强是怎么回事-namespace-还能用吗" aria-hidden="true">#</a> Q12 声明合并和模块增强是怎么回事？namespace 还能用吗？</h3><p><strong>考察点</strong>：考声明合并的规则、<code>declare global</code> 的使用前提，以及 namespace 与现代 ES 模块的取舍。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：同名 interface 会自动合并成员，namespace 可与函数/类/枚举合并；模块增强用来给已存在的模块补类型（如给 Vue 的 this 挂全局属性），而 namespace 在现代代码里已被 ES 模块取代，只建议留在 .d.ts 中。</p></blockquote><ol><li>interface 合并：同名 interface 的成员叠加，同名属性类型不同则报错；常用于给 Window、第三方库接口加字段。</li><li>namespace 合并：namespace 与 function/class/enum 同名可合并，实现&quot;函数加静态成员&quot;的写法，这是老式 JS 习惯的类型表达。</li><li>模块增强：<code>declare module &#39;vue&#39; { interface ComponentCustomProperties { $http: HttpClient } }</code>，只加成员不改已有成员类型。</li><li>全局增强：<code>declare global { interface Window { ... } }</code>，前提是所在文件必须是模块（有 import 或 export），否则会被编译器当成新的声明文件。</li><li>namespace 的问题：会生成运行时 IIFE，不利于 tree-shaking，也不符合 ES 模块规范；能用 import/export 就别用 namespace。</li><li>保留场景：<code>.d.ts</code> 里声明全局类型容器、描述老库的全局变量；<code>declare namespace</code> 只描述类型不产生代码，是安全的。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么给 Vue3 的 this 加属性要写模块增强？答：需要把新成员&quot;并&quot;进已有的 <code>ComponentCustomProperties</code> 接口，直接新声明一个接口不会生效。</li><li>陷阱：在非模块文件里写 <code>declare global</code> 会报 &quot;Augmentations for the global scope can only be directly nested in external modules&quot;，加一行 <code>export {}</code> 即可解决。</li></ul><h3 id="q13-函数类型怎么写-可选参数、默认值和函数重载分别注意什么" tabindex="-1"><a class="header-anchor" href="#q13-函数类型怎么写-可选参数、默认值和函数重载分别注意什么" aria-hidden="true">#</a> Q13 函数类型怎么写？可选参数、默认值和函数重载分别注意什么？</h3><p><strong>考察点</strong>：考函数签名的完整写法与重载（Overload）的规则，包括实现签名对外不可见这个高频追问点。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：函数类型写成 <code>(a: number, b?: string) =&gt; void</code>；可选参数必须在必选参数之后；有默认值的参数在类型上等价于可选；重载是&quot;多个对外的重载签名 + 一个不对外暴露的实现签名&quot;。</p></blockquote><ol><li>可选参数：<code>b?: string</code> 表示调用时可省略，类型上等价于 <code>string | undefined</code>，所以函数体里要判空。</li><li>默认值：<code>function f(a = 1)</code> 的类型是 <code>(a?: number) =&gt; void</code>，参数变成可选；默认值只在传 undefined 时生效（传 null 不会触发）。</li><li>剩余参数：<code>(...args: number[])</code>，注意它必须是最后一个参数，且不能与可选参数写法混用出错。</li><li>重载规则：实现签名对调用方不可见，调用只匹配重载签名列表，所以实现签名要兼容所有重载签名。</li><li>重载 vs 联合参数：如果只是参数类型不同、返回值相同，直接用联合类型更简单；只有&quot;返回值随参数类型变化&quot;时才值得用重载。</li><li>this 类型：<code>function f(this: HTMLButtonElement, e: Event)</code> 可以约束 this，避免误绑定。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">function</span> <span class="token function">pad</span><span class="token punctuation">(</span>v<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
<span class="token keyword">function</span> <span class="token function">pad</span><span class="token punctuation">(</span>v<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">,</span> len<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span>
<span class="token keyword">function</span> <span class="token function">pad</span><span class="token punctuation">(</span>v<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token operator">|</span> <span class="token builtin">number</span><span class="token punctuation">,</span> len <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">{</span> <span class="token comment">// 实现签名不对外可见</span>
  <span class="token keyword">return</span> <span class="token function">String</span><span class="token punctuation">(</span>v<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">padStart</span><span class="token punctuation">(</span>len<span class="token punctuation">,</span> <span class="token string">&#39;0&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：重载和泛型条件类型怎么选？答：重载可读性好、报错清楚；返回值映射关系复杂且要复用类型时用条件类型或泛型。</li><li>陷阱：把实现签名写成 <code>any</code> 来&quot;让它过编译&quot;，等于放弃检查；也不能只写实现签名而期望它有重载行为。</li></ul><h3 id="q14-泛型是什么-extends-约束、泛型默认值和推断顺序讲一下。" tabindex="-1"><a class="header-anchor" href="#q14-泛型是什么-extends-约束、泛型默认值和推断顺序讲一下。" aria-hidden="true">#</a> Q14 泛型是什么？extends 约束、泛型默认值和推断顺序讲一下。</h3><p><strong>考察点</strong>：考泛型作为&quot;类型参数&quot;的本质，以及约束、默认值、推断优先级三件套。答不上推断顺序说明只停留在会用。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：泛型是把类型当参数传入，让类型随调用处自动推断；<code>extends</code> 是约束（不是继承），<code>= </code> 给默认值，推断优先级是显式实参 &gt; 从入参推断 &gt; 默认值。</p></blockquote><ol><li>本质：没有泛型时只能写 <code>function first(arr: any[]): any</code>，用了泛型 <code>function first&lt;T&gt;(arr: T[]): T</code> 才能保留输入输出的类型关联。</li><li>约束 <code>&lt;T extends object&gt;</code>：限制 T 必须具备某些能力，这样才能在函数体里安全访问 <code>T.id</code> 之类的成员。</li><li>常见约束：<code>&lt;T extends object&gt;</code>、<code>&lt;K extends keyof T&gt;</code>、<code>&lt;T extends (...args: any[]) =&gt; any&gt;</code>，后者用在工具类型里限制&quot;必须是函数&quot;。</li><li>默认值 <code>&lt;T = string&gt;</code>：调用方不传也不推断不出来时使用；默认值必须满足约束，否则报错。</li><li>推断顺序：显式传的实参优先，其次由实参值推断，最后才用默认值；显式传入后编译器一般不再从实参纠正。</li><li>判断纪律：如果类型参数只在签名里出现一次、跟返回值无关，那多半不需要泛型，写具体类型更清楚。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">function</span> <span class="token generic-function"><span class="token function">pick</span><span class="token generic class-name"><span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">K</span> <span class="token keyword">extends</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span>obj<span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">,</span> keys<span class="token operator">:</span> <span class="token constant">K</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token operator">:</span> Pick<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">K</span><span class="token operator">&gt;</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> keys<span class="token punctuation">.</span><span class="token function">reduce</span><span class="token punctuation">(</span>
    <span class="token punctuation">(</span>acc<span class="token punctuation">,</span> k<span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">(</span><span class="token punctuation">{</span> <span class="token operator">...</span>acc<span class="token punctuation">,</span> <span class="token punctuation">[</span>k<span class="token punctuation">]</span><span class="token operator">:</span> obj<span class="token punctuation">[</span>k<span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token keyword">as</span> Pick<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">K</span><span class="token operator">&gt;</span><span class="token punctuation">,</span>
  <span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token keyword">const</span> r <span class="token operator">=</span> <span class="token function">pick</span><span class="token punctuation">(</span><span class="token punctuation">{</span> a<span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> b<span class="token operator">:</span> <span class="token string">&#39;x&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string">&#39;a&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// r: { a: number }</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：泛型里的 extends 和 interface 的 extends 是同一个东西吗？答：不是，前者是&quot;约束/上界&quot;，后者是继承。</li><li>陷阱：泛型参数用单字母 T、K、V 混写导致可读性差，业务函数建议用有含义的名字。</li></ul><h3 id="q15-keyof、typeof、索引访问类型、映射类型分别怎么用" tabindex="-1"><a class="header-anchor" href="#q15-keyof、typeof、索引访问类型、映射类型分别怎么用" aria-hidden="true">#</a> Q15 keyof、typeof、索引访问类型、映射类型分别怎么用？</h3><p><strong>考察点</strong>：考四个类型运算符的组合能力，这是理解所有内置工具类型的前置知识。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>keyof T</code> 取属性名联合，<code>typeof expr</code> 取表达式的类型，<code>T[K]</code> 按索引取属性类型，映射类型 <code>{ [K in keyof T]: ... }</code> 遍历键批量改造类型；四者组合就是 Partial、Readonly 这类工具类型的实现方式。</p></blockquote><ol><li><code>keyof T</code>：得到属性名联合；若 T 有索引签名，结果是 <code>string | number</code>；<code>keyof any</code> 是 <code>string | number | symbol</code>。</li><li><code>typeof expr</code>：在类型位置取值的类型，是&quot;从已有常量推导类型&quot;的入口，配合 <code>as const</code> 效果最好。</li><li>索引访问 <code>T[&#39;name&#39;]</code>：取单个属性类型；<code>T[keyof T]</code> 取所有属性类型的联合；数组用 <code>T[number]</code> 取元素类型。</li><li>映射类型：形式是 <code>{ [K in keyof T]: 新类型 }</code>，因为遍历了 <code>keyof T</code>，所以属于同态映射，会自动保留可选与 readonly 修饰。</li><li>修饰符操作：<code>+?</code>/<code>-?</code> 控制可选，<code>+readonly</code>/<code>-readonly</code> 控制只读，<code>as</code> 子句可以重命名或过滤键。</li><li>键重映射的过滤技巧：值类型不匹配时映射成 never，键会被自动丢弃。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">const</span> person <span class="token operator">=</span> <span class="token punctuation">{</span> name<span class="token operator">:</span> <span class="token string">&#39;a&#39;</span><span class="token punctuation">,</span> age<span class="token operator">:</span> <span class="token number">1</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">Person</span> <span class="token operator">=</span> <span class="token keyword">typeof</span> person<span class="token punctuation">;</span>          <span class="token comment">// { name: string; age: number }</span>
<span class="token keyword">type</span> <span class="token class-name">Name</span> <span class="token operator">=</span> Person<span class="token punctuation">[</span><span class="token string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>           <span class="token comment">// string</span>
<span class="token keyword">type</span> <span class="token class-name">Mutable<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token operator">-</span><span class="token keyword">readonly</span> <span class="token punctuation">[</span><span class="token constant">K</span> <span class="token keyword">in</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token punctuation">]</span><span class="token operator">-</span><span class="token operator">?</span><span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">OnlyString<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">[</span><span class="token constant">K</span> <span class="token keyword">in</span> <span class="token keyword">keyof</span> <span class="token constant">T</span> <span class="token keyword">as</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">string</span></span> <span class="token operator">?</span> <span class="token constant">K</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">]</span><span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>keyof typeof obj</code> 为什么这么常用？答：它把常量对象的键变成联合类型，配合它们做安全的字符串参数校验。</li><li>陷阱：在函数内部写 <code>keyof T</code> 的映射类型时忘了 <code>[K in keyof T]</code> 的同态性，会丢掉可选修饰，导致 <code>Partial</code> 这类结果不对。</li></ul><h3 id="q16-条件类型和-infer-是怎么工作的" tabindex="-1"><a class="header-anchor" href="#q16-条件类型和-infer-是怎么工作的" aria-hidden="true">#</a> Q16 条件类型和 infer 是怎么工作的？</h3><p><strong>考察点</strong>：考 <code>X extends Y ? A : B</code> 的求值语义、infer 的合法位置，以及它如何实现类型提取。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：条件类型是类型层面的 if-else，<code>extends</code> 在这里表示&quot;是否可赋值&quot;；<code>infer</code> 只能在 extends 的右侧声明一个待推断变量，用来把类型内部的结构&quot;抠&quot;出来。</p></blockquote><ol><li>求值语义：<code>A extends B ? X : Y</code> 判断 A 是否可赋给 B，可赋值走 X，否则走 Y。</li><li>infer 的位置限制：只能出现在条件类型的 extends 子句里，不能写在函数体或普通类型别名里。</li><li>经典用途：提取 Promise 内的值、函数返回值、数组元素、函数参数元组。</li><li>infer 可加约束（TS 4.7 起）：<code>T extends (infer U extends string)[] ? U : never</code>，避免先推断再报错。</li><li>协变与逆变：在数组、属性等协变位置推断得到联合；在函数参数这种逆变位置，多候选会推断出交叉。</li><li>TS 5.4 的 NoInfer：<code>NoInfer&lt;T&gt;</code> 可以阻止某个位置参与类型推断，用来固定住期望的类型。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">Unwrap<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token keyword">infer</span> <span class="token constant">U</span><span class="token operator">&gt;</span></span> <span class="token operator">?</span> <span class="token constant">U</span> <span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">FnReturn<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">(</span><span class="token operator">...</span>args<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">infer</span> <span class="token constant">R</span> <span class="token operator">?</span> <span class="token constant">R</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">Last<span class="token operator">&lt;</span><span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token builtin">any</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token builtin">any</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token keyword">infer</span> <span class="token constant">L</span><span class="token punctuation">]</span> <span class="token operator">?</span> <span class="token constant">L</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">A</span></span> <span class="token operator">=</span> Unwrap<span class="token operator">&lt;</span><span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token builtin">number</span><span class="token operator">&gt;&gt;</span><span class="token punctuation">;</span>        <span class="token comment">// number</span>
<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">B</span></span> <span class="token operator">=</span> Last<span class="token operator">&lt;</span><span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token builtin">number</span><span class="token punctuation">,</span> <span class="token builtin">boolean</span><span class="token punctuation">]</span><span class="token operator">&gt;</span><span class="token punctuation">;</span> <span class="token comment">// boolean</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 <code>Unwrap&lt;string[]&gt;</code> 是 string[] 而不是报错？答：条件类型不满足时走 false 分支，这里是 T 本身，属于防御式写法。</li><li>陷阱：条件类型默认会对联合类型分发，因此 <code>Unwrap&lt;Promise&lt;1&gt; | Promise&lt;2&gt;&gt;</code> 得到 <code>1 | 2</code> 而不是报错，这是特性不是 bug。</li></ul><h3 id="q17-什么是分布式条件类型-怎么关掉它" tabindex="-1"><a class="header-anchor" href="#q17-什么是分布式条件类型-怎么关掉它" aria-hidden="true">#</a> Q17 什么是分布式条件类型？怎么关掉它？</h3><p><strong>考察点</strong>：考细粒度规则：裸类型参数 + 联合 = 逐成员求值，以及 <code>[T] extends [U]</code> 的关闭技巧。这是类型体操的分水岭。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：当被检查的是&quot;裸类型参数&quot;且传入联合类型时，条件类型会对每个成员分别求值再把结果联合起来；用元组包裹成 <code>[T] extends [U]</code> 就能关闭分发。</p></blockquote><ol><li>触发条件：必须是裸类型参数（naked type parameter），且传入的是联合类型；<code>T extends any ? ...</code> 是最常见的显式分发写法。</li><li>例子：<code>type ToArray&lt;T&gt; = T extends unknown ? T[] : never</code>，传入 <code>string | number</code> 得到 <code>string[] | number[]</code>。</li><li>关闭方式：<code>[T] extends [U] ? A : B</code> 把 T 包进元组，元组类型不是裸参数，于是整体比较，不再逐成员分发。</li><li>never 的特例：裸 never 分发的结果是 never（没有任何成员可分），所以 <code>IsNever</code> 必须写成 <code>[T] extends [never]</code>。</li><li>内置工具类型的依赖：Exclude、Extract、NonNullable 全部依赖分发特性，这也是它们能过滤联合成员的原因。</li><li>注意 boolean：<code>boolean</code> 本质是 <code>true | false</code> 的联合，也会被分发，<code>Diff&lt;boolean, false&gt;</code> 得到 true。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">ToArray<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">unknown</span></span> <span class="token operator">?</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">R1</span></span> <span class="token operator">=</span> ToArray<span class="token operator">&lt;</span><span class="token builtin">string</span> <span class="token operator">|</span> <span class="token builtin">number</span><span class="token operator">&gt;</span><span class="token punctuation">;</span> <span class="token comment">// string[] | number[]</span>

<span class="token keyword">type</span> <span class="token class-name">IsNever<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token constant">T</span><span class="token punctuation">]</span> <span class="token keyword">extends</span> <span class="token punctuation">[</span><span class="token builtin">never</span><span class="token punctuation">]</span> <span class="token operator">?</span> <span class="token boolean">true</span> <span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">IsUnion<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">U</span> <span class="token operator">=</span> <span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token constant">U</span></span> <span class="token operator">?</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token constant">U</span><span class="token punctuation">]</span> <span class="token keyword">extends</span> <span class="token punctuation">[</span><span class="token constant">T</span><span class="token punctuation">]</span> <span class="token operator">?</span> <span class="token boolean">false</span> <span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">)</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">T1</span></span> <span class="token operator">=</span> IsNever<span class="token operator">&lt;</span><span class="token builtin">never</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>            <span class="token comment">// true</span>
<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">T2</span></span> <span class="token operator">=</span> IsUnion<span class="token operator">&lt;</span><span class="token builtin">string</span> <span class="token operator">|</span> <span class="token builtin">number</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>  <span class="token comment">// true</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>T extends any ? X : Y</code> 和直接写 X 有什么区别？答：前者会强制分发，联合类型会变成多个 X 的联合，这是很多类型体操的起手式。</li><li>陷阱：以为 <code>never extends never</code> 会走 true 分支，实际上裸 never 直接返回 never，不会进入任何分支。</li></ul><h3 id="q18-手写-partial、required、readonly、pick、omit、record-并说明内置工具类型的作用。" tabindex="-1"><a class="header-anchor" href="#q18-手写-partial、required、readonly、pick、omit、record-并说明内置工具类型的作用。" aria-hidden="true">#</a> Q18 手写 Partial、Required、Readonly、Pick、Omit、Record，并说明内置工具类型的作用。</h3><p><strong>考察点</strong>：考映射类型与修饰符是否真的会用，而不是只会调 API。要求代码可编译。</p><table><thead><tr><th>工具类型</th><th>作用</th></tr></thead><tbody><tr><td><code>Partial&lt;T&gt;</code></td><td>所有属性变可选（浅层）</td></tr><tr><td><code>Required&lt;T&gt;</code></td><td>所有属性变必填</td></tr><tr><td><code>Readonly&lt;T&gt;</code></td><td>所有属性变只读（浅层）</td></tr><tr><td><code>Pick&lt;T, K&gt;</code></td><td>只保留 K 这些键</td></tr><tr><td><code>Omit&lt;T, K&gt;</code></td><td>去掉 K 这些键</td></tr><tr><td><code>Record&lt;K, V&gt;</code></td><td>构造键为 K、值为 V 的对象类型</td></tr></tbody></table><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：全部由映射类型实现——可选/只读靠 <code>?</code>、<code>readonly</code> 与 <code>-</code> 修饰符，Pick 靠遍历 K，Omit 是 <code>Pick</code> 加 <code>Exclude</code> 的组合，Record 直接遍历 K。</p></blockquote><ol><li><code>Partial</code> 用 <code>?</code> 给每个属性加可选；Required 用 <code>-?</code> 去掉可选；Readonly 用 <code>readonly</code> 前缀，注意这些都是浅层的。</li><li><code>Pick&lt;T, K extends keyof T&gt;</code> 的约束保证了 K 必须是 T 的键，调用方传错键名直接报错。</li><li><code>Omit</code> 的第二参数是 <code>keyof any</code> 而不是 <code>keyof T</code>，所以允许写 T 上不存在的键（宽松但方便）。</li><li><code>Record</code> 遍历的是 K 而不是 <code>keyof T</code>，属于非同态映射，不会保留修饰符。</li><li>使用场景：表单草稿用 Partial，提交参数用 Required，只读配置用 Readonly，列表项展示用 Pick 裁剪字段，创建用 Omit 去掉 id。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">MyPartial<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">[</span><span class="token constant">K</span> <span class="token keyword">in</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token punctuation">]</span><span class="token operator">?</span><span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyRequired<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">[</span><span class="token constant">K</span> <span class="token keyword">in</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token punctuation">]</span><span class="token operator">-</span><span class="token operator">?</span><span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyReadonly<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token keyword">readonly</span> <span class="token punctuation">[</span><span class="token constant">K</span> <span class="token keyword">in</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token punctuation">]</span><span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyPick<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">K</span> <span class="token keyword">extends</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">[</span><span class="token constant">P</span> <span class="token keyword">in</span> <span class="token constant">K</span><span class="token punctuation">]</span><span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">P</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyOmit<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">K</span> <span class="token keyword">extends</span> <span class="token keyword">keyof</span> <span class="token builtin">any</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> MyPick<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> Exclude<span class="token operator">&lt;</span><span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">K</span><span class="token operator">&gt;&gt;</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyRecord<span class="token operator">&lt;</span><span class="token constant">K</span> <span class="token keyword">extends</span> <span class="token keyword">keyof</span> <span class="token builtin">any</span><span class="token punctuation">,</span> <span class="token constant">V</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">[</span><span class="token constant">P</span> <span class="token keyword">in</span> <span class="token constant">K</span><span class="token punctuation">]</span><span class="token operator">:</span> <span class="token constant">V</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name">Draft</span> <span class="token operator">=</span> MyPartial<span class="token operator">&lt;</span><span class="token punctuation">{</span> a<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">;</span> b<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span><span class="token punctuation">;</span> <span class="token comment">// { a?: number; b?: string }</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：Partial 是深层的吗？答：不是，嵌套对象不会变可选，需要 DeepPartial 递归处理。</li><li>陷阱：<code>Pick</code> 的第二个参数写成 <code>K extends keyof T</code> 之外的类型（比如 string）会被拒绝，这是设计上故意的保护。</li></ul><h3 id="q19-手写-exclude、extract、nonnullable、returntype、parameters、awaited。" tabindex="-1"><a class="header-anchor" href="#q19-手写-exclude、extract、nonnullable、returntype、parameters、awaited。" aria-hidden="true">#</a> Q19 手写 Exclude、Extract、NonNullable、ReturnType、Parameters、Awaited。</h3><p><strong>考察点</strong>：考分布式条件类型、infer 与递归的综合运用，是&quot;是否真懂工具类型&quot;的分界线。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Exclude/Extract/NonNullable 靠分布式条件类型过滤成员，ReturnType/Parameters 靠 infer 从函数类型里抽取，Awaited 靠 infer 加递归解包 Promise。</p></blockquote><ol><li><code>Exclude&lt;T, U&gt;</code>：联合 T 的每个成员若可赋给 U 就换成 never，联合吸收 never 即完成删除。</li><li><code>Extract&lt;T, U&gt;</code>：与 Exclude 相反，只保留可赋给 U 的成员，是&quot;取交集&quot;的思路。</li><li><code>NonNullable&lt;T&gt;</code>：本质是 <code>Exclude&lt;T, null | undefined&gt;</code> 的展开写法。</li><li><code>ReturnType</code>/<code>Parameters</code>：先用 <code>T extends (...args: any) =&gt; any</code> 把 T 约束成函数，再用 infer 分别抠出返回值和参数元组。</li><li><code>Awaited</code> 要递归：官方实现还处理 thenable，简化版用 <code>T extends Promise&lt;infer R&gt; ? MyAwaited&lt;R&gt; : T</code> 就能逐层解开 <code>Promise&lt;Promise&lt;number&gt;&gt;</code>。</li><li>重载函数的 ReturnType 取最后一个重载签名；对 any 这类特殊输入，官方实现给的是 any，不要自己改成 never。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">MyExclude<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">U</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token constant">U</span></span> <span class="token operator">?</span> <span class="token builtin">never</span> <span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyExtract<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">,</span> <span class="token constant">U</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token constant">U</span></span> <span class="token operator">?</span> <span class="token constant">T</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyNonNullable<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token keyword">null</span></span> <span class="token operator">|</span> <span class="token keyword">undefined</span> <span class="token operator">?</span> <span class="token builtin">never</span> <span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyReturnType<span class="token operator">&lt;</span><span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">(</span><span class="token operator">...</span>args<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span></span> <span class="token builtin">any</span><span class="token operator">&gt;</span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">(</span><span class="token operator">...</span>args<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">infer</span> <span class="token constant">R</span> <span class="token operator">?</span> <span class="token constant">R</span> <span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyParameters<span class="token operator">&lt;</span><span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">(</span><span class="token operator">...</span>args<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span></span> <span class="token builtin">any</span><span class="token operator">&gt;</span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">(</span><span class="token operator">...</span>args<span class="token operator">:</span> <span class="token builtin">any</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">infer</span> <span class="token constant">P</span> <span class="token operator">?</span> <span class="token constant">P</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">MyAwaited<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token keyword">infer</span> <span class="token constant">R</span><span class="token operator">&gt;</span></span> <span class="token operator">?</span> MyAwaited<span class="token operator">&lt;</span><span class="token constant">R</span><span class="token operator">&gt;</span> <span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">R</span></span> <span class="token operator">=</span> MyReturnType<span class="token operator">&lt;</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token builtin">string</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>      <span class="token comment">// string</span>
<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">P</span></span> <span class="token operator">=</span> MyParameters<span class="token operator">&lt;</span><span class="token punctuation">(</span>a<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">void</span><span class="token operator">&gt;</span><span class="token punctuation">;</span> <span class="token comment">// [a: number]</span>
<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">W</span></span> <span class="token operator">=</span> MyAwaited<span class="token operator">&lt;</span><span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token builtin">Promise</span><span class="token operator">&lt;</span><span class="token number">1</span><span class="token operator">&gt;&gt;&gt;</span><span class="token punctuation">;</span>  <span class="token comment">// 1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>InstanceType</code> 和 <code>ConstructorParameters</code> 怎么实现？答：同样用 infer，把约束换成 <code>abstract new (...args: any) =&gt; any</code> 即可。</li><li>陷阱：把 Exclude 写成 <code>T extends U ? T : never</code> 就变成 Extract 了，这两个实现只差 true 分支，面试时最容易写反。</li></ul><h3 id="q20-模板字面量类型是什么-能拿来做哪些字符串操作" tabindex="-1"><a class="header-anchor" href="#q20-模板字面量类型是什么-能拿来做哪些字符串操作" aria-hidden="true">#</a> Q20 模板字面量类型是什么？能拿来做哪些字符串操作？</h3><p><strong>考察点</strong>：考模板字面量类型（Template Literal Types）与内置字符串操作类型的配合，常用于事件名、路由、CSS 单位建模。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：模板字面量类型把字符串拼接搬到类型层，配合 <code>Uppercase</code>、<code>Capitalize</code> 等内置 intrinsic 类型和联合类型的分发，可以批量生成、约束、解析字符串字面量。</p></blockquote><ol><li>基本形式：<code>\`on\${K}\`</code> 中若 K 是联合，结果自动展开为联合，如 <code>\`on\${&#39;click&#39; | &#39;change&#39;}\`</code> 得到 <code>&#39;onclick&#39; | &#39;onchange&#39;</code>。</li><li>内置字符串操作类型：<code>Uppercase</code>、<code>Lowercase</code>、<code>Capitalize</code>、<code>Uncapitalize</code>，作用是改大小写且保留联合。</li><li>解析能力：配合 infer 可以按分隔符拆分字符串，做路由参数提取、CSS 属性值校验。</li><li>与映射类型结合：用 <code>as</code> 键重映射批量生成 getter/setter 名称，是状态管理类型定义的常见写法。</li><li>约束能力：写成 <code>\`\${number}px\`</code> 这样的模板字面量类型，就能约束只接受 px 字符串，比 string 精确得多。</li><li>限制：模板字面量类型只对字符串字面量有意义，宽 string 无法被反向解析，运行时的模板字符串也不受影响。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">EventName</span> <span class="token operator">=</span> <span class="token string">&#39;click&#39;</span> <span class="token operator">|</span> <span class="token string">&#39;change&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">OnEvent</span> <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">on</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>Capitalize<span class="token operator">&lt;</span>EventName<span class="token operator">&gt;</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span> <span class="token comment">// &#39;onClick&#39; | &#39;onChange&#39;</span>

<span class="token keyword">type</span> <span class="token class-name">Join<span class="token operator">&lt;</span><span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token builtin">string</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token constant">D</span> <span class="token keyword">extends</span> <span class="token builtin">string</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span>
  <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">?</span> <span class="token string">&#39;&#39;</span>
    <span class="token operator">:</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token punctuation">[</span><span class="token keyword">infer</span> <span class="token constant">F</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">string</span></span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token keyword">infer</span> <span class="token constant">R</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">string</span></span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">]</span>
      <span class="token operator">?</span> <span class="token constant">R</span> <span class="token keyword">extends</span> <span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">?</span> <span class="token constant">F</span> <span class="token operator">:</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">F</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token constant">D</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span>Join<span class="token operator">&lt;</span><span class="token constant">R</span><span class="token punctuation">,</span> <span class="token constant">D</span><span class="token operator">&gt;</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span>
      <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name">Route</span> <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token string">/user/</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token builtin">string</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">Padded</span> <span class="token operator">=</span> <span class="token template-string"><span class="token template-punctuation string">\`</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">\${</span><span class="token builtin">number</span><span class="token interpolation-punctuation punctuation">}</span></span><span class="token string">px</span><span class="token template-punctuation string">\`</span></span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：能不能从 <code>string</code> 反推出模板结构？答：不能，只有字面量类型才有结构信息，宽 string 无法匹配解析。</li><li>陷阱：把模板字面量类型当成运行时格式化工具，它编译后完全不存在，实际拼接仍要写模板字符串。</li></ul><h3 id="q21-怎么写递归类型-deepreadonly-为什么不能无限递归" tabindex="-1"><a class="header-anchor" href="#q21-怎么写递归类型-deepreadonly-为什么不能无限递归" aria-hidden="true">#</a> Q21 怎么写递归类型？DeepReadonly 为什么不能无限递归？</h3><p><strong>考察点</strong>：考递归条件类型的写法与编译器限制，以及函数、Map 这类特殊值该怎么处理。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：递归类型就是在定义里引用自己，靠条件类型提供终止分支；深度受编译器实例化上限约束，所以必须先判函数和原始类型再递归对象，不能无界展开。</p></blockquote><ol><li>终止条件必不可少：原始类型直接返回自身，否则会一直递归到报错。</li><li>处理函数：函数类型没有可映射的属性，直接映射会变成 <code>{}</code>，所以要在最前面用 <code>T extends Function ? T</code> 挡掉。</li><li>Map、Set、Date 这类内置对象要单独保留，否则会被映射成普通对象类型，破坏原有的方法签名。</li><li>数组的特别之处：同态映射类型作用在数组/元组上会保留数组结构，所以 <code>DeepReadonly&lt;number[]&gt;</code> 会得到 <code>readonly number[]</code>。</li><li>深度限制：TS 对类型实例化深度有上限（约 50 层），超过会报 <code>Type instantiation is excessively deep</code>；TS 4.5 起对尾递归的条件类型做了尾递归消除，深度可提升到约 1000 层。</li><li>工程建议：深度工具类型限制在 3 到 5 层、加上 readOnly 或哨兵标记，并在类型测试里固定行为。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">DeepReadonly<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">Function</span></span>
  <span class="token operator">?</span> <span class="token constant">T</span>
  <span class="token operator">:</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name">object</span>
    <span class="token operator">?</span> <span class="token punctuation">{</span> <span class="token keyword">readonly</span> <span class="token punctuation">[</span><span class="token constant">K</span> <span class="token keyword">in</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token punctuation">]</span><span class="token operator">:</span> DeepReadonly<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span><span class="token operator">&gt;</span> <span class="token punctuation">}</span>
    <span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name">DeepPartial<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span> <span class="token constant">T</span> <span class="token keyword">extends</span> <span class="token class-name">object</span>
  <span class="token operator">?</span> <span class="token punctuation">{</span> <span class="token punctuation">[</span><span class="token constant">K</span> <span class="token keyword">in</span> <span class="token keyword">keyof</span> <span class="token constant">T</span><span class="token punctuation">]</span><span class="token operator">?</span><span class="token operator">:</span> DeepPartial<span class="token operator">&lt;</span><span class="token constant">T</span><span class="token punctuation">[</span><span class="token constant">K</span><span class="token punctuation">]</span><span class="token operator">&gt;</span> <span class="token punctuation">}</span>
  <span class="token operator">:</span> <span class="token constant">T</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name"><span class="token constant">A</span></span> <span class="token operator">=</span> DeepReadonly<span class="token operator">&lt;</span><span class="token punctuation">{</span> a<span class="token operator">:</span> <span class="token punctuation">{</span> b<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span><span class="token punctuation">;</span> <span class="token comment">// { readonly a: { readonly b: readonly number[] } }</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么类型体操写太深会让编辑器卡？答：tsserver 要为每个文件实例化这些类型，递归与交叉类型没有缓存，成本会叠加。</li><li>陷阱：直接对任意泛型写 <code>[K in keyof T]: DeepReadonly&lt;T[K]&gt;</code> 而不排除 Function，结果会把函数类型映射成 <code>{}</code>，调用时报错。</li></ul><h3 id="q22-uniontointersection-是怎么实现的-类型体操的边界在哪" tabindex="-1"><a class="header-anchor" href="#q22-uniontointersection-是怎么实现的-类型体操的边界在哪" aria-hidden="true">#</a> Q22 UnionToIntersection 是怎么实现的？类型体操的边界在哪？</h3><p><strong>考察点</strong>：考逆变位置推断这个高级机制，以及工程师视角的取舍判断——不能只炫技。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：先用分布式条件类型把联合的每个成员包装成&quot;参数是该成员&quot;的函数类型，再用 infer 在函数参数这个逆变位置推断，多个候选会被合成为交叉类型。</p></blockquote><ol><li>第一步分发：<code>U extends unknown ? (arg: U) =&gt; void : never</code>，联合 <code>A | B</code> 变成 <code>((arg: A) =&gt; void) | ((arg: B) =&gt; void)</code>。</li><li>第二步推断：整体去匹配 <code>(arg: infer I) =&gt; void</code>，由于参数位置是逆变位，候选 A 与 B 会推断为 <code>A &amp; B</code>。</li><li>直觉来源：函数参数位置本来就要求&quot;能接受更宽的类型&quot;，多个候选同时满足时就取交集，这与 strictFunctionTypes 的规则一致。</li><li>用途：把多个组件的 props 联合合成一个交叉对象、合并 key 集合，以及实现 UnionToTuple 之类高级工具。</li><li>价值边界：类型体操应该服务于&quot;让业务代码不写类型&quot;，一旦复杂到需要注释才能读懂，就应该退化成显式展开的类型。</li><li>成本意识：每个复杂类型都会增加编译时间与报错噪音；团队项目要配类型测试（类型断言用例），否则重构时无人敢动。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">type</span> <span class="token class-name">UnionToIntersection<span class="token operator">&lt;</span><span class="token constant">U</span><span class="token operator">&gt;</span></span> <span class="token operator">=</span>
  <span class="token punctuation">(</span><span class="token constant">U</span> <span class="token keyword">extends</span> <span class="token class-name"><span class="token builtin">unknown</span></span> <span class="token operator">?</span> <span class="token punctuation">(</span>arg<span class="token operator">:</span> <span class="token constant">U</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">void</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">)</span> <span class="token keyword">extends</span> <span class="token punctuation">(</span>arg<span class="token operator">:</span> <span class="token keyword">infer</span> <span class="token constant">I</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">void</span> <span class="token operator">?</span> <span class="token constant">I</span> <span class="token operator">:</span> <span class="token builtin">never</span><span class="token punctuation">;</span>

<span class="token keyword">type</span> <span class="token class-name">Merged</span> <span class="token operator">=</span> UnionToIntersection<span class="token operator">&lt;</span><span class="token punctuation">{</span> a<span class="token operator">:</span> <span class="token builtin">number</span> <span class="token punctuation">}</span> <span class="token operator">|</span> <span class="token punctuation">{</span> b<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span><span class="token punctuation">;</span>
<span class="token comment">// { a: number } &amp; { b: string }</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么结果不是联合而是交叉？答：因为 infer 处在函数参数位置（逆变位），多候选会求交集；若放在返回值位置（协变位）则会得到联合。</li><li>陷阱：把 UnionToIntersection 当成运行时的对象合并使用，它只在类型层面成立，运行时仍要用 Object.assign 或展开语法。</li></ul><h3 id="q23-enum、const-enum-和联合字面量该怎么选" tabindex="-1"><a class="header-anchor" href="#q23-enum、const-enum-和联合字面量该怎么选" aria-hidden="true">#</a> Q23 enum、const enum 和联合字面量该怎么选？</h3><p><strong>考察点</strong>：考枚举的产物差异与现代打包链的兼容问题，能说清&quot;为什么很多团队禁 enum&quot;才算过关。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：数值 enum 会生成运行时对象和反向映射，字符串 enum 只有运行时对象，const enum 编译期内联但逐文件转译器支持不好；现代项目更推荐 <code>as const</code> 对象加联合字面量，零运行时、tree-shaking 友好。</p></blockquote><ol><li>数值 enum 产物：编译成 <code>{ 0: &#39;A&#39;, A: 0 }</code> 这样的双向映射对象，体积最大，还能被 <code>Object.keys</code> 遍历出一半数字键。</li><li>字符串 enum 产物：只有 <code>{ A: &#39;a&#39; }</code> 一个方向的映射；异构 enum（数字与字符串混写）虽然合法但不建议。</li><li>const enum：使用时被内联成字面量，不生成运行时对象；代价是必须整个程序一起编译，逐文件转译的 babel/esbuild 默认处理不了（需要插件），<code>isolatedModules</code> 下访问环境常量枚举会直接报错。</li><li>联合字面量的优势：完全没有运行时产物、与后端 JSON 值天然对应、可以和 <code>as const</code> 对象配合同时拿到值与类型。</li><li>TS 5.8 的 <code>erasableSyntaxOnly</code>：开启后 enum、namespace 这类不可擦除语法会直接报错，适合交给 Node 或打包器剥离类型的项目。</li><li>选型：纯前端业务常量用 as const 对象；需要与后端数值协议对齐或做位运算时用数值 enum；const enum 只适合老式全量 tsc 编译的项目。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">const</span> Status <span class="token operator">=</span> <span class="token punctuation">{</span> Pending<span class="token operator">:</span> <span class="token string">&#39;pending&#39;</span><span class="token punctuation">,</span> Done<span class="token operator">:</span> <span class="token string">&#39;done&#39;</span> <span class="token punctuation">}</span> <span class="token keyword">as</span> <span class="token keyword">const</span><span class="token punctuation">;</span>
<span class="token keyword">type</span> <span class="token class-name">Status</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token keyword">typeof</span> Status<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token keyword">keyof</span> <span class="token keyword">typeof</span> Status<span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token comment">// &#39;pending&#39; | &#39;done&#39;</span>

<span class="token keyword">function</span> <span class="token function">render</span><span class="token punctuation">(</span>s<span class="token operator">:</span> Status<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">return</span> s <span class="token operator">===</span> Status<span class="token punctuation">.</span>Pending <span class="token operator">?</span> <span class="token string">&#39;加载中&#39;</span> <span class="token operator">:</span> <span class="token string">&#39;完成&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：enum 在类型收窄上比联合字面量更强吗？答：不强，联合字面量的收窄与穷尽检查一样好用，两者类型能力相当。</li><li>陷阱：在 Vite 项目里用 const enum 会遇到跨模块访问报错或行为不一致，团队要提前约定。</li></ul><h3 id="q24-declare-和-d-ts-怎么用-第三方库没有类型怎么办" tabindex="-1"><a class="header-anchor" href="#q24-declare-和-d-ts-怎么用-第三方库没有类型怎么办" aria-hidden="true">#</a> Q24 declare 和 .d.ts 怎么用？第三方库没有类型怎么办？</h3><p><strong>考察点</strong>：考声明文件的实际编写能力，包括 @types 体系、declare module 的三种形态和全局增强的前提。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>declare</code> 只声明类型、不生成任何运行时代码；第三方库无类型时先看 <code>@types/包名</code>，没有就自己写 .d.ts 用 <code>declare module</code> 描述，模块通配符则用来处理 <code>*.vue</code>、<code>*.svg</code> 这类非 TS 文件。</p></blockquote><ol><li>优先级：库里自带 types 字段 &gt; 社区 <code>@types/xxx</code>（DefinitelyTyped）&gt; 自己写声明文件。</li><li>声明文件放置：放在 <code>src/types/</code> 或 <code>types/</code> 目录，通过 tsconfig 的 <code>include</code> 纳入；用 <code>typeRoots</code>/<code>types</code> 控制自动加载的包。</li><li>具体模块声明：<code>declare module &#39;legacy-lib&#39; { ... }</code> 描述一个真实存在的模块，内部可写 export 与 default。</li><li>通配符声明：<code>declare module &#39;*.vue&#39;</code>、<code>declare module &#39;*.svg&#39;</code> 用于告诉编译器这些后缀如何被当模块导入。</li><li>全局增强：<code>declare global</code> 必须写在模块文件里，用来给 Window 等已存在的接口加成员。</li><li>容错技巧：<code>@ts-expect-error</code> 会在&quot;其实没报错&quot;时反过来报错，比 <code>@ts-ignore</code> 安全；<code>skipLibCheck</code> 可以跳过所有 .d.ts 的检查来加速并绕开依赖里的类型冲突。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// src/types/legacy-lib.d.ts</span>
<span class="token comment">// 本文件不能有 import/export，否则会被当成&quot;模块增强&quot;并报模块找不到</span>
<span class="token keyword">declare</span> <span class="token keyword">module</span> <span class="token string">&#39;legacy-lib&#39;</span> <span class="token punctuation">{</span>
  <span class="token keyword">export</span> <span class="token keyword">function</span> <span class="token function">init</span><span class="token punctuation">(</span>options<span class="token operator">?</span><span class="token operator">:</span> <span class="token punctuation">{</span> debug<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">boolean</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span><span class="token punctuation">;</span>
  <span class="token keyword">const</span> api<span class="token operator">:</span> <span class="token punctuation">{</span> version<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>
  <span class="token keyword">export</span> <span class="token keyword">default</span> api<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// src/types/global.d.ts</span>
<span class="token comment">// 有 export 才是模块，declare global 才生效</span>
<span class="token keyword">declare</span> global <span class="token punctuation">{</span>
  <span class="token keyword">interface</span> <span class="token class-name">Window</span> <span class="token punctuation">{</span> __APP_VERSION__<span class="token operator">:</span> <span class="token builtin">string</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
<span class="token keyword">export</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>declare module &#39;*.vue&#39;</code> 里写什么？答：默认导出组件的类型，Vue 项目里通常由 <code>vue-tsc</code> 或 <code>@vue/runtime-dom</code> 提供，无需自己写。</li><li>陷阱：以为 <code>declare</code> 会生成运行时代码。<code>declare const foo = 1</code> 能通过编译（环境 <code>const</code> 允许字面量初始值，<code>declare var</code> 带初始值才会报错），但产物里没有任何赋值，运行时访问 <code>foo</code> 会抛 <code>ReferenceError</code>。</li></ul><h3 id="q25-tsconfig-里哪些配置最关键-类型检查太慢怎么优化" tabindex="-1"><a class="header-anchor" href="#q25-tsconfig-里哪些配置最关键-类型检查太慢怎么优化" aria-hidden="true">#</a> Q25 tsconfig 里哪些配置最关键？类型检查太慢怎么优化？</h3><p><strong>考察点</strong>：考工程化配置的理解，重点是每个选项&quot;影响什么&quot;，以及性能排查手段。前端面试的高频工程题。</p><table><thead><tr><th>配置</th><th>作用</th><th>常见取值</th></tr></thead><tbody><tr><td><code>strict</code></td><td>打开全套严格检查（含 strictNullChecks）</td><td>新项目 true</td></tr><tr><td><code>target</code></td><td>输出语法等级，并决定默认引入的 <code>lib</code>（影响可用 API）</td><td>ES2019 / ES2020</td></tr><tr><td><code>module</code> / <code>moduleResolution</code></td><td>模块格式与解析策略</td><td>ESNext + Bundler；Node 项目 NodeNext</td></tr><tr><td><code>paths</code></td><td>路径别名，只影响类型解析</td><td><code>&quot;@/*&quot;: [&quot;src/*&quot;]</code></td></tr><tr><td><code>skipLibCheck</code></td><td>跳过所有 .d.ts 的检查</td><td>true</td></tr><tr><td><code>isolatedModules</code></td><td>保证每个文件可独立转译</td><td>true</td></tr><tr><td><code>noEmit</code></td><td>只检查不产出</td><td>CI 里用</td></tr><tr><td><code>incremental</code></td><td>增量编译缓存</td><td>true</td></tr></tbody></table><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：<code>strict</code> 决定检查强度，<code>target</code> 决定产出语法，<code>module</code> 与 <code>moduleResolution</code> 决定模块解析方式，<code>paths</code> 只管类型不管运行时，<code>skipLibCheck</code> 与 <code>isolatedModules</code> 决定构建链兼容与速度。</p></blockquote><ol><li><code>skipLibCheck</code> 跳过所有声明文件的类型检查，能显著提速，代价是依赖里的类型冲突不会暴露；它不会跳过你自己项目源码的检查。</li><li><code>isolatedModules</code> 强制每个文件可独立转译，是 Vite、babel、esbuild 这类逐文件工具的前提，开启后要显式用 <code>export type</code>。</li><li><code>paths</code> 的别名只影响类型解析，运行时必须由打包器（Vite、webpack）或 Node 单独配置，否则编译通过但运行时报模块找不到。</li><li>性能排查：<code>tsc --extendedDiagnostics</code> 看检查耗时分布，<code>tsc --generateTrace</code> 分析类型实例化热点。</li><li>优化手段：缩小 <code>include</code> 范围、<code>incremental</code> 缓存、monorepo 用 project references 拆分、用 <code>import type</code> 减少类型依赖图、避免大范围深层交叉与递归类型。</li><li>常见坑：编辑器卡顿往往来自某个巨型 .d.ts 或某个文件里的复杂类型，而不是整体配置问题，要定位到具体文件。</li></ol><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>target</code> 会影响类型检查结果吗？答：会影响部分库类型（如 lib 推断出的 API 差异）与降级语法，但不做类型强度判断，类型严格性由 strict 家族决定。</li><li>陷阱：以为配了 <code>paths</code> 就万事大吉，Vite 里还得在 <code>resolve.alias</code> 同步一份，否则类型过了、运行时报错。</li></ul><h3 id="q26-tsc-和-babel、esbuild-编译-typescript-有什么区别" tabindex="-1"><a class="header-anchor" href="#q26-tsc-和-babel、esbuild-编译-typescript-有什么区别" aria-hidden="true">#</a> Q26 tsc 和 babel、esbuild 编译 TypeScript 有什么区别？</h3><p><strong>考察点</strong>：考&quot;类型检查&quot;与&quot;类型擦除&quot;是两件事，以及 isolatedModules 存在的原因。答不出这点说明没踩过坑。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：tsc 同时做类型检查和代码生成；babel、esbuild、swc 只擦除类型、逐文件转译，速度快但不做任何类型检查，所以现代前端的类型检查交给 <code>tsc --noEmit</code> 或 <code>vue-tsc</code>。</p></blockquote><ol><li>定位差异：tsc 是编译器兼类型检查器，esbuild 用 Go 写、只做语法剥离，所以能快一个数量级。</li><li>工程实践：Vite 用 esbuild 转译 TS，CI 里单独跑 <code>tsc --noEmit</code> 或 <code>vue-tsc --noEmit</code> 做类型门禁。</li><li>逐文件转译的代价：不理解跨文件类型，所以必须开 <code>isolatedModules</code>，类型导出要用 <code>export type</code>，否则类型被当成值导出会在运行时消失。</li><li>const enum 与 namespace：依赖全局分析，逐文件转译器默认不支持，需要插件或改用联合字面量。</li><li>兼容标记：<code>verbatimModuleSyntax</code>（TS 5.0）要求显式区分 <code>import type</code> 与 <code>import</code>，能避免转译后残留无效 import。</li><li>结论：转译器负责产码速度，tsc 负责类型正确性，两者职责分离是现代前端构建的共识。</li></ol><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tsc <span class="token parameter variable">--noEmit</span>                       <span class="token comment"># CI 里只做类型检查，不产文件</span>
esbuild src/main.ts <span class="token parameter variable">--bundle</span> <span class="token parameter variable">--outfile</span><span class="token operator">=</span>dist/app.js
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：为什么 Vite 里写了类型错误还能跑起来？答：Vite 走 esbuild 只擦类型不检查，错误要在编辑器或 CI 的 tsc 阶段才暴露。</li><li>陷阱：以为&quot;能编译就能上线&quot;，没配 <code>tsc --noEmit</code> 门禁的项目里类型错误会一路带进生产环境。</li></ul><h3 id="q27-vue3-和-react-项目里-ts-有哪些高频实战写法" tabindex="-1"><a class="header-anchor" href="#q27-vue3-和-react-项目里-ts-有哪些高频实战写法" aria-hidden="true">#</a> Q27 Vue3 和 React 项目里 TS 有哪些高频实战写法？</h3><p><strong>考察点</strong>：考框架侧的类型 API 是否真的用过：defineProps 泛型、InjectionKey、事件类型、useRef 泛型。答不出来会显得只有语法基础。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：Vue3 用 <code>defineProps&lt;T&gt;()</code> 和 <code>defineEmits&lt;T&gt;()</code> 的泛型写法替代运行时声明，用 <code>InjectionKey&lt;T&gt;</code> 让 provide/inject 有类型；React 用 <code>useRef&lt;T&gt;</code>、<code>useState&lt;T&gt;</code> 和 <code>React.ChangeEvent&lt;T&gt;</code> 这类事件泛型约束 DOM 与状态。</p></blockquote><ol><li>Vue3 defineProps：<code>defineProps&lt;{ title: string }&gt;()</code>；带默认值用 <code>withDefaults(defineProps&lt;T&gt;(), { ... })</code>，因为泛型声明不能直接写默认值。</li><li>Vue3 版本差异：3.3 起支持更复杂的类型（如导入的外部类型与联合），更早版本只能用类型字面量。</li><li>Vue3 事件：<code>defineEmits&lt;{ change: [id: number] }&gt;()</code> 是 3.3+ 的命名元组语法，旧写法是调用签名 <code>(e: &#39;change&#39;, id: number): void</code>。</li><li>InjectionKey：<code>const cartKey: InjectionKey&lt;CartApi&gt; = Symbol(&#39;cart&#39;)</code>，注入端就能拿到类型，避免 any。</li><li>React ref：<code>useRef&lt;HTMLInputElement&gt;(null)</code> 让 <code>ref.current</code> 有类型；React 19 的类型定义里 useRef 必须传初始值，不再有无参重载。</li><li>React 事件与组件类型：事件用 <code>React.ChangeEvent&lt;HTMLInputElement&gt;</code>；React 18 起 <code>FC</code> 不再隐式带 children，要显式用 <code>PropsWithChildren</code>。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token comment">// Vue 3.3+</span>
<span class="token keyword">const</span> props <span class="token operator">=</span> <span class="token generic-function"><span class="token function">defineProps</span><span class="token generic class-name"><span class="token operator">&lt;</span><span class="token punctuation">{</span> title<span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">;</span> tags<span class="token operator">?</span><span class="token operator">:</span> <span class="token builtin">string</span><span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> emit <span class="token operator">=</span> <span class="token generic-function"><span class="token function">defineEmits</span><span class="token generic class-name"><span class="token operator">&lt;</span><span class="token punctuation">{</span> change<span class="token operator">:</span> <span class="token punctuation">[</span>id<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">]</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">export</span> <span class="token keyword">const</span> cartKey<span class="token operator">:</span> InjectionKey<span class="token operator">&lt;</span><span class="token punctuation">{</span> <span class="token function">add</span><span class="token punctuation">(</span>n<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span> <span class="token punctuation">}</span><span class="token operator">&gt;</span> <span class="token operator">=</span> <span class="token function">Symbol</span><span class="token punctuation">(</span><span class="token string">&#39;cart&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// React 18/19</span>
<span class="token keyword">const</span> inputRef <span class="token operator">=</span> <span class="token generic-function"><span class="token function">useRef</span><span class="token generic class-name"><span class="token operator">&lt;</span>HTMLInputElement<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">function</span> <span class="token function">onChange</span><span class="token punctuation">(</span>e<span class="token operator">:</span> React<span class="token punctuation">.</span>ChangeEvent<span class="token operator">&lt;</span>HTMLInputElement<span class="token operator">&gt;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token function">setValue</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>target<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：<code>defineProps</code> 泛型能传导入的 interface 吗？答：Vue 3.3 起可以，3.3 之前编译器无法解析外部类型引用，会报错。</li><li>陷阱：<code>useRef&lt;number&gt;(0)</code> 与 <code>useRef&lt;number | null&gt;(null)</code> 的行为不同，前者 current 永远有值，判空写法要根据初始值来定，别为了少写一个判断而写错。</li></ul><h3 id="q28-常见误区-用了-typescript-是不是就不用做运行时校验了" tabindex="-1"><a class="header-anchor" href="#q28-常见误区-用了-typescript-是不是就不用做运行时校验了" aria-hidden="true">#</a> Q28 常见误区：用了 TypeScript 是不是就不用做运行时校验了？</h3><p><strong>考察点</strong>：考对&quot;类型擦除&quot;的工程理解，能不能分清编译期契约与运行时可信边界。这是最容易被追问的总结性题目。</p><p><strong>参考答案</strong>：</p><blockquote><p><strong>一句话结论</strong>：不能，类型编译后会被完全擦除，TypeScript 只管住你自己写的代码，管不住接口返回、<code>JSON.parse</code>、localStorage、URL 参数和用户输入，这些边界必须做运行时校验。</p></blockquote><ol><li>擦除的本质：<code>.ts</code> 编译后就是 <code>.js</code>，接口、泛型、断言运行时都不存在，<code>interface</code> 不会变成对象。</li><li>典型翻车：<code>const data = (await res.json()) as User</code> 编译零错误，后端少字段时崩在业务渲染深处。</li><li>正确做法：在系统边界做运行时校验（zod、valibot 或手写类型守卫），把 unknown 校验成可信类型后再向内传递。</li><li>其他常见误区：用 any 图快、用 <code>!</code> 非空断言掩盖空值、用 <code>@ts-ignore</code> 熄火、以为&quot;改了类型就能改运行时行为&quot;。</li><li>反向的坑：类型写得比运行时更严格（如把可选字段标成必填），会把真实数据挡在类型层之外，逼得同事到处写 as。</li><li>心智模型：类型是&quot;编译期的契约 + 编辑器的提示&quot;，运行时安全靠校验、测试与防御性编程，两者互补而不是替代。</li></ol><div class="language-typescript line-numbers-mode" data-ext="ts"><pre class="language-typescript"><code><span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token function">loadUser</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">const</span> parsed <span class="token operator">=</span> UserSchema<span class="token punctuation">.</span><span class="token function">safeParse</span><span class="token punctuation">(</span><span class="token keyword">await</span> res<span class="token punctuation">.</span><span class="token function">json</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// zod 等运行时校验</span>
  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>parsed<span class="token punctuation">.</span>success<span class="token punctuation">)</span> <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">Error</span><span class="token punctuation">(</span><span class="token string">&#39;bad payload&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
  <span class="token keyword">return</span> parsed<span class="token punctuation">.</span>data<span class="token punctuation">;</span> <span class="token comment">// 到这里才是类型安全且运行时有保障的</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>追问与易错点</strong>：</p><ul><li>追问：那 <code>as const</code> 和类型守卫算不算运行时校验？答：类型守卫函数体里是真的在判断（typeof、in），所以算；<code>as</code> 不算。</li><li>陷阱：面试时回答&quot;有 TS 就不会类型错误&quot;会被追问接口数据形状，正确答案必须落到&quot;边界处校验&quot;。</li></ul><h2 id="本章小结" tabindex="-1"><a class="header-anchor" href="#本章小结" aria-hidden="true">#</a> 本章小结</h2><ul><li>TypeScript 的价值是把类型错误前移到编译期并提供工具能力，代价是编写与检查成本；类型在编译后会被擦除，不提供任何运行时保障。</li><li>TS 是结构化类型系统，只看形状是否兼容；用品牌类型可以模拟名义类型，避免语义不同的同形状类型互相赋值。</li><li>any 关掉检查，unknown 是安全的顶类型必须收窄后用，never 是没有任何值的底类型，是穷尽检查与 Exclude 的基础。</li><li>打开 strictNullChecks 后 null/undefined 成为独立类型，空值必须显式处理；<code>!</code> 与 <code>as</code> 都只是给编译器的承诺，不是运行时校验。</li><li>interface 适合可扩展、可合并的对象形状，type 适合联合、元组与类型运算；两者在描述对象时高度重叠，团队一致性优先。</li><li>泛型靠 extends 约束、靠默认值兜底，推断优先级是显式实参大于入参推断大于默认值；只出现一次的类型参数通常不需要泛型。</li><li>手写工具类型的底座只有三件事：映射类型加修饰符、分布式条件类型、infer 提取；把这三件学会就能推导大部分内置工具类型。</li><li>类型体操要服务于&quot;让业务代码不写类型&quot;，深递归、UnionToIntersection 这类写法必须配注释与类型测试，否则是负资产。</li><li>tsconfig 里 strict、target、module、moduleResolution、paths、skipLibCheck、isolatedModules 决定检查强度与构建链兼容；转译交给 esbuild、类型检查交给 tsc --noEmit。</li></ul>`,226);function c(l,i){return s(),a("div",null,[p,t(" COUNT: 28 ")])}const d=n(o,[["render",c],["__file","15-typescript.html.vue"]]);export{d as default};
